import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak, monitor_flag_rate, pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"c": []}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (2, 7), (5, 8)])
def test_window(days, expected):
    assert flags_in_window([1, 3, 4], days) == expected


def test_parse_whitespace_and_flags():
    events = parse_transcript_log(["", " \t", " # ignored", " a , 1 , 0", "b,2, ", "c,3,1"])
    assert events == [
        {"id": "a", "day": 1, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "c", "day": 3, "flagged": True},
    ]


@pytest.mark.parametrize("bad", ["a,1", "a,1,0,", "a,today,1"])
def test_parse_error_reports_input_line(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "a,1,1", " ", bad])


def test_dedupe_keeps_last_record_and_sorts():
    first, b, c, last = parse_transcript_log(["a,4,1", "b,2,0", "c,1,1", "a,2,0"])
    assert dedupe_transcripts([first, b, c, last]) == [c, last, b]


def test_daily_counts():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,4,1", "f,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["a,1,1", "b,5,1"]),
              "b": parse_transcript_log(["c,5,0"]), "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"flagged": True}], "a": [{"flagged": None}],
              "b": [{"flagged": True}], "empty": []}
    assert top_flagged_groups(groups, 1) == ["b"]
    assert top_flagged_groups(groups, 5) == ["b", "z", "a"]


def test_group_rates_in_name_order():
    groups = {"z": [{"flagged": None}], "x": [], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("x", None), ("z", 0.0)]


@pytest.mark.parametrize("counts,expected", [([], 0), ([0, -1], 0), ([1, 0, 2, 3, -1, 2], 2)])
def test_longest_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
